INSERT INTO playbooks (id, client_id, task_type, version, content_json, created_by, created_at) VALUES ('pb_apn-demo_supplier_bill_1', 'apn-demo', 'supplier_bill', 1, '{"voice_guide":"Warm, plain and brief. Use the tenant''s first name. One idea per paragraph. No jargon, no exclamation marks. Never promise a date or outcome the source or our records don''t support. Never discuss other tenants, owners'' finances or bank details.","sign_off":"Property Management Team\nAPN Demo Realty","own_names":["APN Demo Realty","Property Management Team","APN Demo"],"rules":["Reply only to the sender of the email.","Never include bank account details in a reply.","Never agree to rent changes, bond releases or lease changes; say a property manager will follow up.","Anything mentioning a tribunal, ombudsman, lawyer or regulator goes to a senior property manager.","Dates are written like Tue 4 Nov 2026."],"faq":[{"topic":"rent_payment","keywords":["direct debit","bpay","pay rent","pay my rent","rent payment"],"answer":"You can pay rent by BPAY or direct debit. Your rent of {rent_weekly} per week is due each {rent_due_day}."},{"topic":"rent_amount","keywords":["my rent is","behind","arrears","ledger"],"answer":"Our records show your rent is {rent_weekly} per week, due each {rent_due_day}. We''ll check your rent ledger and come back to you."},{"topic":"pets","keywords":["pet","dog","cat"],"answer":"Pets need the owner''s written approval. We''ll ask the owner and let you know."},{"topic":"repairs","keywords":["broken","repair","fix","leak","dripping","not working"],"answer":"We''ve logged the repair and we''ll arrange for a tradesperson to contact you within 2 business days."},{"topic":"inspection_reschedule","keywords":["inspection"],"also":["move","reschedule","instead","change"],"answer":"We''ve noted your request to move the inspection to {requested_date}. We''ll confirm the new time shortly."},{"topic":"bond","keywords":["bond"],"answer":"Bond refunds are lodged with NSW Fair Trading once the final inspection is complete. We''ll be in touch about the next steps."}]}', 'seed', '2026-10-23T00:00:00.000Z');
